@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ## Part 1 — A four-page toy web

    Four pages, five links: A links to B and C, B links to C, C links to A, and D links to C.
    Nobody links to D.

    A surfer on a page picks one of its links with equal probability, so column $j$ of $P$ has
    $1/\text{outdeg}(j)$ in the rows of the pages $j$ links to and 0 elsewhere. Every column
    adds up to 1: $P$ is *column-stochastic*.
    """)
    return


@app.cell
def _(np):
    pages_toy = ["A", "B", "C", "D"]
    # column j: where a surfer on page j goes next. A links to B and C; B to C; C to A; D to C.
    P_toy = np.array([[0,   0, 1, 0],
                      [0.5, 0, 0, 0],
                      [0.5, 1, 0, 1],
                      [0,   0, 0, 0]])
    assert np.allclose(P_toy.sum(axis=0), 1)    # column-stochastic: every column sums to 1
    return P_toy, pages_toy


