    mo.md(
        md_table(["Page", "no damping (α = 1)", f"α = {alpha:.2f}"], _rows)
        + "\n\nDamping takes probability away from where the links concentrate it and spreads "
        "it evenly, so every page, D included, ends up with a positive score. The slider stops "
        "short of α = 1 because there $I - P$ is singular (the eigenvalue 1 again), and the "
        "answer is the eigenvector worked out by hand."
    )
