@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Power iteration: just keep clicking

    For a web of billions of pages nobody solves the system directly. Instead, start from any
    distribution and apply $G$ over and over. Each step is one round of clicking. The error
    shrinks roughly by the factor $|\lambda_2|$, the second-largest eigenvalue size of $G$,
    at every step, and damping guarantees $|\lambda_2| \le \alpha$.
    """)
    return


@app.cell
def _(G_toy, n_toy, np, r_toy):
    r = np.full(n_toy, 1 / n_toy)               # start from the uniform distribution
    history = [r]
    for _ in range(40):
        r = G_toy @ r                           # one round of clicking
        history.append(r)
    errors = [abs(h - r_toy).sum() for h in history]
    lambda2_toy = sorted(abs(np.linalg.eigvals(G_toy)))[-2]   # second-largest |eigenvalue|
    return errors, history, lambda2_toy


@app.cell(hide_code=True)
def _(julia):
    julia("power", " (with α = 0.85)")
    return


@app.cell
def _(alpha, errors, history, lambda2_toy, np, pages_toy, plt):
    _fig, (_ax1, _ax2) = plt.subplots(1, 2, figsize=(9, 3.2))
    _h = np.array(history)
    for _i, _c in enumerate(["#1d4ed8", "#d97706", "#059669", "#7c3aed"]):
        _ax1.plot(_h[:16, _i], "o-", ms=3, color=_c, label=f"page {pages_toy[_i]}")
    _ax1.set_xlabel("clicks t")
    _ax1.set_ylabel("probability of being on the page")
    _ax1.set_title("The distribution settles")
    _ax1.legend(frameon=False, fontsize=8)
    _k = np.arange(len(errors))
    _ok = np.array(errors) > 1e-15
    _ax2.semilogy(_k[_ok], np.array(errors)[_ok], "o-", ms=3, color="#1d4ed8",
                  label="error after t clicks")
    _ax2.semilogy(_k, errors[0] * lambda2_toy ** _k, "--", color="#555",
                  label=f"|λ₂|ᵗ = {lambda2_toy:.3f}ᵗ")
    _ax2.set_xlabel("clicks t")
    _ax2.set_title(f"Error shrinks like |λ₂|ᵗ (α = {alpha:.2f})")
    _ax2.legend(frameon=False, fontsize=8)
