@app.cell(hide_code=True)
def _(alpha, lambda2_toy, mo, np):
    mo.md(
        f"Here $|\\lambda_2(G)| = {lambda2_toy:.4f}$, which is exactly "
        f"$\\alpha \\cdot |\\lambda_2(P)| = {alpha:.2f} \\times {np.sqrt(0.5):.4f}$. "
        "Damping shrinks every eigenvalue of $P$ except the 1 by the factor α, which is why α "
        "controls how fast the iteration converges."
    )
