@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Two ways for undamped clicking to go wrong

    The random jumps are not a detail. Change one link in the toy web and the undamped surfer
    misbehaves.

    - **A web that goes round in a circle.** Delete the link A → C. Now A → B → C → A is a
      loop, and a surfer who starts on A is on A again every third click, forever: the
      distribution never settles. $P$ now has three eigenvalues of size 1 (the cube roots of
      1), so there is no gap for power iteration to use.
    - **A page with no links.** Delete D's only link instead. Column D of $P$ becomes all
      zeros, $P$ is no longer stochastic, and every surfer who reaches D vanishes. The total
      probability drains away. The standard patch, a *modeling decision*, is to treat a
      *dangling node* as linking to every page.
    """)
    return


@app.cell
def _(P_toy, np):
    P_cycle = P_toy.copy()
    P_cycle[:, 0] = [0, 1, 0, 0]                # delete the link A → C: now A → B → C → A
    r_cycle = np.array([1.0, 0, 0, 0])          # start on page A
    cycle_undamped = [r_cycle]
    for _ in range(30):
        r_cycle = P_cycle @ r_cycle             # no damping: the surfer never settles
        cycle_undamped.append(r_cycle)
    assert np.allclose(cycle_undamped[30], cycle_undamped[27])   # period 3, forever
    eigenvalues_cycle = np.linalg.eigvals(P_cycle)
    assert np.allclose(sorted(abs(eigenvalues_cycle))[-3:], 1)   # three eigenvalues on |λ| = 1
    return P_cycle, cycle_undamped


@app.cell(hide_code=True)
def _(julia):
    julia("periodic")
    return


@app.cell
def _(P_toy, alpha, n_toy, np):
    P_dang = P_toy.copy()
    P_dang[:, 3] = 0                            # delete D's link: column D is now all zeros
    r_naive = np.full(n_toy, 1 / n_toy)
    for _ in range(200):
        r_naive = alpha * (P_dang @ r_naive) + (1 - alpha) / n_toy   # unpatched: probability leaks away
    mass_naive = r_naive.sum()
    dangling_toy = P_dang.sum(axis=0) == 0
    P_patched = P_dang + np.outer(np.ones(n_toy), dangling_toy) / n_toy   # D now links to every page
    r_dang = np.linalg.solve(np.eye(n_toy) - alpha * P_patched, (1 - alpha) / n_toy * np.ones(n_toy))
    assert np.isclose(r_dang.sum(), 1)
    return P_dang, P_patched, mass_naive, r_dang


@app.cell(hide_code=True)
def _(julia):
    julia("dangling", " (with α = 0.85)")
    return


@app.cell
def _(P_cycle, P_dang, P_patched, alpha, cycle_undamped, n_toy, np, plt):
    _fig, (_ax1, _ax2) = plt.subplots(1, 2, figsize=(9, 3.2))
    _damped = [np.array([1.0, 0, 0, 0])]
    for _ in range(30):
        _damped.append(alpha * (P_cycle @ _damped[-1]) + (1 - alpha) / n_toy)
    _ax1.plot([v[0] for v in cycle_undamped], "o-", ms=3, color="#d97706", label="α = 1")
    _ax1.plot([v[0] for v in _damped], "o-", ms=3, color="#1d4ed8", label=f"α = {alpha:.2f}")
    _ax1.set_xlabel("clicks t")
    _ax1.set_ylabel("probability of being on A")
    _ax1.set_title("Loop A → B → C → A, starting on A")
    _ax1.set_ylim(-0.05, 1.3)
    _ax1.legend(frameon=False, fontsize=8, loc="upper center", ncol=2)
    _naive, _patched = [np.full(n_toy, 1 / n_toy)], [np.full(n_toy, 1 / n_toy)]
    for _ in range(30):
        _naive.append(alpha * (P_dang @ _naive[-1]) + (1 - alpha) / n_toy)
        _patched.append(alpha * (P_patched @ _patched[-1]) + (1 - alpha) / n_toy)
    _ax2.plot([v.sum() for v in _naive], "o-", ms=3, color="#d97706", label="dangling D left as is")
    _ax2.plot([v.sum() for v in _patched], "o-", ms=3, color="#1d4ed8",
              label="D treated as linking everywhere")
    _ax2.set_ylim(0, 1.05)
    _ax2.set_xlabel("clicks t")
    _ax2.set_ylabel("total probability")
    _ax2.set_title(f"D has no links (α = {alpha:.2f})")
    _ax2.legend(frameon=False, fontsize=8, loc="lower left")
    _fig.tight_layout()
    _fig
    return


