@app.cell
def _(links, np, titles):
    n_wiki = len(titles)
    outdeg = np.array([len(row) for row in links])
    P_wiki = np.zeros((n_wiki, n_wiki))
    for _j, _row in enumerate(links):
        if _row:
            P_wiki[_row, _j] = 1 / len(_row)    # column j: 1/outdeg(j) on each article j links to
    indeg = (P_wiki > 0).sum(axis=1)            # number of articles that link to each article
    dangling = outdeg == 0
    assert np.allclose(P_wiki.sum(axis=0)[~dangling], 1) and dangling.sum() >= 1
    return P_wiki, dangling, indeg, n_wiki, outdeg


