@app.cell(hide_code=True)
def _(dangling, indeg, mo, n_wiki, np, outdeg, titles):
    _dang = ", ".join(f"*{titles[j]}*" for j in np.where(dangling)[0])
    _orphans = ", ".join(f"*{titles[j]}*" for j in np.where(indeg == 0)[0])
    mo.md(
        f"The network has **{n_wiki} articles and {outdeg.sum():,} links**, so $P$ is "
        f"{n_wiki} × {n_wiki} with {outdeg.sum():,} nonzero entries: "
        f"{100 * outdeg.sum() / n_wiki**2:.0f}% full. The real web is far sparser, which is "
        "why PageRank is always computed from $P$ and never from the dense $G$.\n\n"
        f"- **Dangling:** {_dang} links to none of the other articles, so its column of $P$ "
        "is zero, the second pitfall of Part 1 met in real data.\n"
        f"- **No in-links:** {_orphans}. Like page D, these are reached only by random jumps, "
        "so they all get the minimum possible score."
    )
    return


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Computing PageRank

    The function below is power iteration as it is done at scale. It never forms $G$: each
    step multiplies by the sparse $P$, adds back the probability that fell into dangling
    nodes, and adds the random jumps. Both corrections are rank-one terms, so they cost $O(n)$
    instead of $O(n^2)$. It stops when a step changes the vector by less than $10^{-10}$
    (summed over all pages).
    """)
    return


@app.cell
def _(np):
    def pagerank(P, alpha, v=None, tol=1e-10, max_iter=1000):
        """Power iteration for r = α S r + (1 − α) v, never forming G or S. S is P with each
        dangling (all-zero) column replaced by 1/n everywhere; v is where random jumps land,
        uniform unless given. Returns (r, errors): the change made by each step."""
        n = P.shape[0]
        v = np.full(n, 1 / n) if v is None else v
        dangling = P.sum(axis=0) == 0
        r, errors = np.full(n, 1 / n), []
        for _ in range(max_iter):
            r_next = alpha * (P @ r) + alpha * r[dangling].sum() / n + (1 - alpha) * v
            errors.append(abs(r_next - r).sum())
            r = r_next
            if errors[-1] < tol:
                break
        return r, errors
    return (pagerank,)


@app.cell
def _(mo):
    alpha_wiki_slider = mo.ui.slider(0.05, 0.99, step=0.01, value=0.85,
                                     label="Damping factor α for Wikipedia", show_value=True)
    alpha_wiki_slider
    return (alpha_wiki_slider,)


@app.cell
def _(P_wiki, alpha_wiki_slider, np, pagerank):
    alpha_wiki = alpha_wiki_slider.value
    r_wiki, errors_wiki = pagerank(P_wiki, alpha_wiki)
    assert np.isclose(r_wiki.sum(), 1) and (r_wiki > 0).all() and len(errors_wiki) < 1000
    return alpha_wiki, errors_wiki, r_wiki


