@app.cell(hide_code=True)
def _(alpha_wiki, errors_wiki, indeg, md_table, mo, np, r_wiki, titles):
    _rank_in = 1 + (indeg[None, :] > indeg[:, None]).sum(axis=1)   # ties share a rank
    _rows = [[k + 1, titles[j], f"{r_wiki[j]:.4f}", indeg[j], _rank_in[j]]
             for k, j in enumerate(np.argsort(-r_wiki)[:20])]
    mo.md(
        f"### The top 20 (α = {alpha_wiki:.2f}, {len(errors_wiki)} iterations)\n\n"
        f"A uniform score would be 1/{len(titles)} = {1 / len(titles):.4f}.\n\n"
        + md_table(["Rank", "Article", "PageRank", "in-links", "rank by in-links"], _rows)
    )
    return


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### PageRank is not just counting links

    Counting in-links (*in-degree centrality*) is the obvious alternative. The two rankings
    mostly agree, but not everywhere: under PageRank a link from a heavily visited article is
    worth more than a link from a rarely visited one, and a link from an article with few
    links is worth more than one from an article with many, because the surfer's probability
    is split among the links.
    """)
    return


@app.cell
def _(indeg, np, plt, r_wiki, titles):
    _rank_pr = np.argsort(np.argsort(-r_wiki))
    _rank_in = (indeg[None, :] > indeg[:, None]).sum(axis=1)
    _gain = _rank_in - _rank_pr                 # positive: PageRank ranks it higher
    _fig, _ax = plt.subplots(figsize=(7.5, 4.8))
    _ax.scatter(indeg, r_wiki, s=14, color="#94a3b8")
    _top_y, _max_x = r_wiki.max(), indeg.max()
    _ups = sorted(np.argsort(-_gain)[:4], key=lambda j: -r_wiki[j])
    _downs = sorted(np.argsort(_gain)[:3], key=lambda j: -r_wiki[j])
    # labels in two empty corners, joined to their points by thin lines
    for _k, _j in enumerate(_ups):
        _ax.annotate(titles[_j], (indeg[_j], r_wiki[_j]), fontsize=7, color="#1d4ed8",
                     xytext=(0.02 * _max_x, (0.92 - 0.08 * _k) * _top_y),
                     arrowprops=dict(arrowstyle="-", color="#1d4ed8", lw=0.6))
        _ax.scatter(indeg[_j], r_wiki[_j], s=22, color="#1d4ed8", zorder=3)
    for _k, _j in enumerate(_downs):
        _ax.annotate(titles[_j], (indeg[_j], r_wiki[_j]), fontsize=7, color="#d97706",
                     xytext=(0.45 * _max_x, (0.22 - 0.07 * _k) * _top_y),
                     arrowprops=dict(arrowstyle="-", color="#d97706", lw=0.6))
        _ax.scatter(indeg[_j], r_wiki[_j], s=22, color="#d97706", zorder=3)
    for _j in np.argsort(-r_wiki)[:3]:
        _ax.annotate(titles[_j], (indeg[_j], r_wiki[_j]), fontsize=7, color="#334155",
                     xytext=(-4, 4), textcoords="offset points", ha="right")
    _ax.set_xlabel("in-links (articles in the set that link to it)")
    _ax.set_ylabel("PageRank")
    _ax.set_title("Blue: ranked much higher by PageRank; orange: much lower", fontsize=10)
    _fig.tight_layout()
    _fig
    return


@app.cell(hide_code=True)
def _(P_wiki, indeg, links, mo, np, outdeg, r_wiki, titles):
    _rank_pr = np.argsort(np.argsort(-r_wiki)) + 1
    _rank_in = 1 + (indeg[None, :] > indeg[:, None]).sum(axis=1)   # ties share a rank
    _up = int(np.argmax(_rank_in - _rank_pr))
    _down = int(np.argmin(_rank_in - _rank_pr))
    _sources = sorted(np.where(P_wiki[_up] > 0)[0], key=lambda j: -r_wiki[j])
    _src = ", ".join(f"*{titles[j]}* (rank {_rank_pr[j]}, {outdeg[j]} links)" for j in _sources)
    _dsrc = [j for j in range(len(titles)) if _down in links[j]]
    _links_per = np.mean(outdeg[_dsrc])
    mo.md(
        f"The biggest gain is **{titles[_up]}**: {indeg[_up]} in-links (rank {_rank_in[_up]} "
        f"by count) but PageRank rank {_rank_pr[_up]}. Its in-links come from {_src}.\n\n"
        f"The biggest drop is **{titles[_down]}**: {indeg[_down]} in-links (rank "
        f"{_rank_in[_down]} by count) but PageRank rank {_rank_pr[_down]}. The articles that "
        f"link to it have {_links_per:.1f} links each on average, against {outdeg.mean():.1f} "
        "for the whole set, so each of their links passes on only a small share of their "
        "probability."
    )
    return


@app.cell
def _(np, plt, r_wiki, titles, P_wiki):
    _order = np.argsort(-r_wiki)
    _i, _j = np.nonzero(P_wiki[np.ix_(_order, _order)])
    _fig, _ax = plt.subplots(figsize=(5.4, 5.4))
    _ax.scatter(_j, _i, s=1.5, color="#1d4ed8", marker="s", linewidths=0)
    _ax.set_xlim(-1, len(titles))
    _ax.set_ylim(len(titles), -1)
    _ax.set_aspect("equal")
    _ax.set_xlabel("linking article j (sorted by PageRank)")
    _ax.set_ylabel("linked article i (sorted by PageRank)")
    _ax.set_title("Nonzero entries of P, highest PageRank first", fontsize=10)
    _fig.tight_layout()
    _fig
    return


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    The dense band at the top is what PageRank detects: almost every article, whatever its
    own rank, links to the handful of foundational ones (vector space, matrix, linear map), so
    probability flows up to them from everywhere.

    ### How fast does it converge?

    For the toy, $|\lambda_2(G)| = \alpha\,|\lambda_2(P)|$. The same holds for any web, once
    the dangling columns are patched (call the patched matrix $S$): every eigenvalue of $S$
    except the 1 is multiplied by α. So α is only an upper bound on the convergence factor,
    and a well-connected network converges faster than that.
    """)
    return


@app.cell
def _(alpha_wiki, dangling, n_wiki, np, P_wiki):
    S_wiki = P_wiki + np.outer(np.ones(n_wiki), dangling) / n_wiki   # dangling columns patched
    G_wiki = alpha_wiki * S_wiki + (1 - alpha_wiki) / n_wiki         # formed only to check
    lambda2_S = sorted(abs(np.linalg.eigvals(S_wiki)))[-2]
    lambda2_G = sorted(abs(np.linalg.eigvals(G_wiki)))[-2]
    assert np.isclose(lambda2_G, alpha_wiki * lambda2_S) and lambda2_G <= alpha_wiki
    return lambda2_G, lambda2_S


@app.cell(hide_code=True)
def _(julia):
    julia("convergence", " (with α = 0.85)")
    return


@app.cell
def _(P_wiki, alpha_wiki, errors_wiki, lambda2_G, lambda2_S, np, pagerank, plt):
    _fig, (_ax1, _ax2) = plt.subplots(1, 2, figsize=(9.5, 3.4))
    _k = np.arange(1, len(errors_wiki) + 1)
    _ax1.semilogy(_k, errors_wiki, "o-", ms=3, color="#1d4ed8", label="change per step")
    _ax1.semilogy(_k, errors_wiki[0] * lambda2_G ** (_k - 1), "--", color="#555",
                  label=f"|λ₂(G)|ᵏ = {lambda2_G:.3f}ᵏ")
    _ax1.semilogy(_k, errors_wiki[0] * alpha_wiki ** (_k - 1), ":", color="#d97706",
                  label=f"αᵏ = {alpha_wiki:.2f}ᵏ (the bound)")
    _ax1.set_xlabel("iteration k")
    _ax1.set_title(f"α = {alpha_wiki:.2f}: {len(errors_wiki)} iterations to 10⁻¹⁰", fontsize=10)
    _ax1.legend(frameon=False, fontsize=8)
    _alphas = np.array([0.5, 0.6, 0.7, 0.8, 0.85, 0.9, 0.95, 0.99])
    _iters = [len(pagerank(P_wiki, a)[1]) for a in _alphas]
    _pred = [np.log(1e-10) / np.log(a * lambda2_S) for a in _alphas]
    _ax2.plot(_alphas, _iters, "o-", color="#1d4ed8", label="Wikipedia network")
    _ax2.plot(_alphas, _pred, "--", color="#555", label="log 10⁻¹⁰ / log(α |λ₂(S)|)")
    _ax2.plot(_alphas, [np.log(1e-10) / np.log(a) for a in _alphas], ":", color="#d97706",
              label="log 10⁻¹⁰ / log α (worst case)")
    _ax2.set_yscale("log")
    _ax2.set_xlabel("damping factor α")
    _ax2.set_ylabel("iterations")
    _ax2.set_title(f"|λ₂(S)| = {lambda2_S:.3f} here, so α near 1 stays cheap", fontsize=10)
    _ax2.legend(frameon=False, fontsize=8)
    _fig.tight_layout()
    _fig
    return


@app.cell(hide_code=True)
def _(alpha_wiki, lambda2_G, lambda2_S, mo):
    mo.md(
        f"With α = {alpha_wiki:.2f}: $|\\lambda_2(S)| = {lambda2_S:.4f}$ and "
        f"$|\\lambda_2(G)| = {lambda2_G:.4f} = {alpha_wiki:.2f} \\times {lambda2_S:.4f}$. "
        "On the real web $|\\lambda_2(S)|$ is 1 or very close to it, because the web contains "
        "groups of pages that link only among themselves. There the bound α is the actual rate, "
        "and α = 0.85 is a compromise: closer to 1 follows the links more faithfully, but "
        "needs many more iterations and makes the ranking more sensitive to small changes in "
        "the links."
    )
    return


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Personalized PageRank: articles near one article

    The random jumps need not land uniformly. If every jump returns to a single article, the
    surfer never strays far from it, and the scores measure how close every other article is
    to that one through the links. Replace the uniform jump vector $\frac1n\mathbf{1}$ with a
    vector $v$ that is 1 for the chosen article and 0 elsewhere:

    $$r = \alpha S r + (1 - \alpha)\, v.$$

    This *personalized PageRank* is used for recommendations ("related articles") and as a
    similarity measure between the nodes of a graph.

    The raw scores are still dominated by the hubs: from any article, the links lead to
    *Vector space* and *Matrix* within a click or two. Dividing by the ordinary PageRank gives
    the *lift*, how many times more often the surfer visits an article because of where the
    jumps land. Ranking by lift picks out the articles specific to the chosen one.
    """)
    return


@app.cell
def _(mo, titles):
    target_dropdown = mo.ui.dropdown(options=titles, value="Singular value decomposition",
                                     label="Every random jump returns to", searchable=True)
    target_dropdown
    return (target_dropdown,)


@app.cell
def _(P_wiki, alpha_wiki, n_wiki, np, pagerank, target_dropdown, titles):
    target = titles.index(target_dropdown.value)   # the dropdown
    v = np.zeros(n_wiki)
    v[target] = 1                               # every random jump returns to one article
    r_pers, _ = pagerank(P_wiki, alpha_wiki, v=v)
    lift = r_pers / r_wiki                      # > 1: visited more because jumps return to target
    assert np.isclose(r_pers.sum(), 1) and np.argmax(r_pers) == target
    return lift, r_pers, target


@app.cell(hide_code=True)
def _(julia):
    julia("personalized", " (for Singular value decomposition, with α = 0.85)")
    return


@app.cell(hide_code=True)
def _(lift, md_table, mo, np, r_pers, r_wiki, target, titles):
    _by_score = [j for j in np.argsort(-r_pers) if j != target][:5]
    _by_lift = [j for j in np.argsort(-lift) if j != target][:10]
    _rows = [[k + 1, titles[j], f"{lift[j]:.1f}", f"{r_pers[j]:.4f}", f"{r_wiki[j]:.4f}"]
             for k, j in enumerate(_by_lift)]
    mo.md(
        f"**Closest to {titles[target]}**, ranked by lift (its own score is "
        f"{r_pers[target]:.3f}). By raw personalized score the top five would be "
        + ", ".join(f"*{titles[j]}*" for j in _by_score) + ": the hubs again.\n\n"
        + md_table(["", "Article", "lift", "personalized score", "ordinary PageRank"], _rows)
    )
    return


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ## Notes

    - **Never form $G$.** $G$ is dense: for $n$ pages it has $n^2$ entries, all positive. The
      iteration needs only products with the sparse $P$ plus rank-one corrections, so each step
      costs about as much as reading the links once.
    - **Patching dangling nodes is a modeling decision.** Sending a dangling node's surfers
      anywhere at random (as here) is one convention. Sending them back along the jump vector
      $v$, or removing dangling nodes and adding them back afterwards, are others, and they
      give somewhat different rankings.
    - **Why the answer exists and is unique.** With α < 1 every entry of $G$ is positive, and
      the Perron–Frobenius theorem says that a positive matrix has a single largest eigenvalue,
      with an eigenvector whose entries are all positive. For a column-stochastic matrix that
      eigenvalue is 1. The random jumps are there to make that theorem apply.
    - **The answer is not in a subspace.** PageRank vectors are nonnegative and add up to 1,
      so they live in the *probability simplex* inside $\mathbb{R}^n$, not in a subspace: the
      sum of two PageRank vectors is not one.
    """)
    return


